INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (10040, "あたしだって\nやるときはやるよ！", 102601, 24001, "2020/04/30 12:00:00", 24, 0, 1, 0.0, "2030/12/17 14:59:59", 0.0, "リン", 1, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (10040, "ふぅ…\nこれであたしの仕事は\n終わりだね", 102601, 24002, "2020/04/30 12:00:00", 24, 1, 1, 0.0, "2030/12/17 14:59:59", 0.0, "リン", 1, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (10040, "終わった終わった\n一人でもなんとか\nなるもんだね", 102601, 24003, "2020/04/30 12:00:00", 24, 2, 1, 0.0, "2030/12/17 14:59:59", 0.0, "リン", 1, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (10040, "やったね！\nこれでようやく\nサボれるよ…", 102601, 24004, "2020/04/30 12:00:00", 24, 3, 2, 0.0, "2030/12/17 14:59:59", 0.0, "リン", 2, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (10040, "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", 102601, 24005, "2020/04/30 12:00:00", 24, 4, 1, 0.0, "2030/12/17 14:59:59", 0.0, "リン", 1, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (10040, "あたしを敵に回した\n恐ろしさ\n思い知ったか！", 102601, 24006, "2020/04/30 12:00:00", 24, 5, 2, 0.0, "2030/12/17 14:59:59", 0.0, "リン", 2, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (10040, "あたしも意外と\nやるもんでしょ？", 102601, 24007, "2020/04/30 12:00:00", 24, 6, 2, 0.0, "2030/12/17 14:59:59", 0.0, "リン", 2, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (10040, "疲れた…\nねずみの逃げ足\n速すぎるよ…", 102601, 24008, "2020/04/30 12:00:00", 24, 7, 4, 0.0, "2030/12/17 14:59:59", 0.0, "リン", 4, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (10040, "このままじゃ\nまっひ～に\n叱られちゃうよ", 102601, 24009, "2020/04/30 12:00:00", 24, 8, 4, 0.0, "2030/12/17 14:59:59", 0.0, "リン", 4, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (10040, "まじめに\nやったんだけどな…\n悔しいな～", 102601, 24010, "2020/04/30 12:00:00", 24, 9, 4, 0.0, "2030/12/17 14:59:59", 0.0, "リン", 4, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (10040, "やられた…\nねずみって意外と\nてごわいね", 102601, 24011, "2020/04/30 12:00:00", 24, 10, 4, 0.0, "2030/12/17 14:59:59", 0.0, "リン", 4, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (10040, "おのれ～\nあたしのチーズを\n盗みやがって～！", 102601, 24012, "2020/04/30 12:00:00", 24, 11, 4, 0.0, "2030/12/17 14:59:59", 0.0, "リン", 4, 0.0);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES (10040, "疲れた…\nけど、次こそは\n守り抜くよ…", 102601, 24013, "2020/04/30 12:00:00", 24, 12, 1, 0.0, "2030/12/17 14:59:59", 0.0, "リン", 4, 1.81);
